@startuml

enum AttendeeStatus {
  Yes
  Maybe
  No
}

enum TaskStatus {
  ToBeDone
  Done
  NotApplicable
}

class Person {
  + FirstName : string
  + LastName : string
  + EmailAddress : string
  + Password : string
}

class Organizer extends Person {
  + Address : string
  + PhoneNumber : string
}

class Attendee extends Person {
  + Password : string
}

class EventType {
  + Name : string
}

class Event {
  + StartDateTime : datetime
  + EndDateTime : datetime
  + Occasion : string
}

class Location {
  + Name : string
  + Address : string
}

class Task {
  + Description : string
  + Status : TaskStatus
}

class Invitation {
  + Status : string
}

class Assignment {
}

Organizer "1..*" -- "0..*" Event : organizes
Organizer "0..*" -- "0..*" Event : attends
Attendee "0..*" -- "0..*" Event : attends
Event "*" -- "1" EventType : is of type
Event "*" -- "1" Location : held at
Event "1" *-- "*" Task : has checklist
Task "0..*" -- "0..1" Attendee : assigned to
Attendee "0..*" -- "0..*" Task : brings

@enduml

